    case path = "path"
    case request = "request"
    case minted = "minted"
}

/// Static description of a queued call's opto-sync record.
public struct RidlOptoSyncBinding: Equatable {
    public let table: String
    public let operation: String
    public let from: RidlRecordIdFrom
    public let name: String?

    public init(table: String, operation: String, from: RidlRecordIdFrom, name: String?) {
        self.table = table; self.operation = operation
        self.from = from; self.name = name
    }
}

/// One outbound call, fully resolved. Transports never re-derive paths.
public struct RidlRequest {
    public let key: String
    public let method: String
    public let path: String
    /// The unsubstituted template, so a transport can locate a named
    /// parameter inside `path` instead of guessing at its position.
    public let pathTemplate: String
    public let query: [(String, String)]
    public let body: Data?
    public let delivery: RidlDelivery
    public let optoSync: RidlOptoSyncBinding?

    public init(key: String, method: String, path: String, pathTemplate: String = "", query: [(String, String)] = [], body: Data? = nil, delivery: RidlDelivery = .direct, optoSync: RidlOptoSyncBinding? = nil) {
        self.key = key; self.method = method; self.path = path
        self.pathTemplate = pathTemplate
        self.query = query; self.body = body
        self.delivery = delivery; self.optoSync = optoSync
    }
}

/// The single seam between generated code and the network.
///
/// Implement it over URLSession for direct calls and over an opto-sync queue
/// for queued ones. The dependency runs one way: this module calls
/// opto-sync, never the reverse.
public protocol RidlTransport {
    func call(_ request: RidlRequest) async throws -> Data
}

/// Escape one path segment so an id containing `/` cannot reshape the URL.
public func ridlEncodeSegment(_ value: String) -> String {
    value.addingPercentEncoding(withAllowedCharacters: .alphanumerics) ?? value
}

/// `GET /healthz`
public func healthzPath() -> String {
    return "/healthz"
}

/// `POST /v1/matters`
public func createMatterPath() -> String {
    return "/v1/matters"
}

/// `GET /v1/matters/{id}`
public func getMatterPath(_ id: MatterId) -> String {
    return "/v1/matters/\(ridlEncodeSegment("\(id)"))"
}

/// `POST /v1/matters/{id}/walk`
public func walkMatterPath(_ id: MatterId) -> String {
    return "/v1/matters/\(ridlEncodeSegment("\(id)"))/walk"
}

/// `GET /v1/matters/{id}/documents`
public func getDocumentsPath(_ id: MatterId) -> String {
    return "/v1/matters/\(ridlEncodeSegment("\(id)"))/documents"
}

/// `GET /v1/matters/{id}/facts`
public func getFactsPath(_ id: MatterId) -> String {
    return "/v1/matters/\(ridlEncodeSegment("\(id)"))/facts"
}

/// `GET /v1/avenues`
public func avenuesPath() -> String {
    return "/v1/avenues"
}

/// `GET /v1/geography`
public func geographyPath() -> String {
    return "/v1/geography"
}

/// `POST /pmap.v1.Interview/CheckFieldSanity`
public func checkFieldSanityPath() -> String {
    return "/pmap.v1.Interview/CheckFieldSanity"
}

/// `POST /pmap.v1.Interview/AskCounsel`
public func askCounselPath() -> String {
    return "/pmap.v1.Interview/AskCounsel"
}

/// `POST /v1/fields/sanity`
public func checkFieldSanityRestPath() -> String {
    return "/v1/fields/sanity"
}

public func healthz(_ transport: RidlTransport) async throws -> String {
    let path = healthzPath()
    let pairs: [(String, String)] = []
    let raw = try await transport.call(RidlRequest(
